-- PostgreSQL trigram indexes for Helix search filters.
--
-- List/search endpoints filter text with ILIKE '%term%', which a btree index
-- cannot serve. A pg_trgm GIN index makes those scans index-assisted for large
-- tenants. Generated from the ILIKE predicates in server/services; regenerate
-- after adding new searchable columns. Requires the pg_trgm extension (created
-- in schema.sql).

-- Retired trigram indexes. notification_events and numbering_allocations are
-- among the highest-churn write paths and their ILIKE filters are low value, so
-- the GIN write amplification is not worth it. They are dropped here so that
-- already-provisioned databases converge with the pruned set; the matching
-- CREATE INDEX statements have been removed below.
DROP INDEX IF EXISTS idx_trgm_notification_events_event_type_raw;
DROP INDEX IF EXISTS idx_trgm_notification_events_initiator_username_raw;
DROP INDEX IF EXISTS idx_trgm_notification_events_object_name_raw;
DROP INDEX IF EXISTS idx_trgm_notification_events_payload_json_raw;
DROP INDEX IF EXISTS idx_trgm_numbering_allocations_allocation_ref;
DROP INDEX IF EXISTS idx_trgm_numbering_allocations_number;
DROP INDEX IF EXISTS idx_trgm_numbering_allocations_object_id;
DROP INDEX IF EXISTS idx_trgm_numbering_allocations_object_ref;

